def transform(grid):
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    h, w = len(grid), len(grid[0])

    for r in range(h):
        markers = [c for c, value in enumerate(grid[r]) if value != background]
        for left, right in zip(markers, markers[1:]):
            for c in range(left + 1, right):
                if grid[r][c] == background:
                    out[r][c] = 3

    for c in range(w):
        markers = [r for r in range(h) if grid[r][c] != background]
        for top, bottom in zip(markers, markers[1:]):
            for r in range(top + 1, bottom):
                if grid[r][c] == background:
                    out[r][c] = 3
    return out
